html:
{% set p = get_wholesale_print_data(doc) %}{% set show_images = 1 if doc.get('custom_print_color_images') is none else doc.get('custom_print_color_images') %}{% set show_item_name = 1 if doc.get('custom_print_item_name') is none else doc.get('custom_print_item_name') %}{% set show_sku = 1 if doc.get('custom_print_sku') is none else doc.get('custom_print_sku') %}{% set show_color_code = 1 if doc.get('custom_print_color_code') is none else doc.get('custom_print_color_code') %}{% set show_description = 1 if doc.get('custom_print_description') is none else doc.get('custom_print_description') %}
<style>
  .wholesale-title { text-align: center; margin-bottom: 18px; }
  .wholesale-meta { width: 100%; margin-bottom: 14px; }
  .wholesale-items { width: 100%; border-collapse: collapse; }
  .wholesale-items th, .wholesale-items td { border: 1px solid #d1d8dd; padding: 7px 6px; vertical-align: middle; }
  .wholesale-items th { background: #f5f7f9; }
  .wholesale-image { width: 42px; height: 42px; object-fit: cover; }
  .wholesale-qr-list { display: flex; gap: 18px; flex-wrap: wrap; margin-top: 18px; }
  .wholesale-qr { display: flex; align-items: center; gap: 7px; }
  .wholesale-qr img { width: 62px; height: 62px; }
</style>
<h2 class='wholesale-title'>{{ _('批发销售单') }}</h2>
<table class='wholesale-meta'>
  <tr><td><b>{{ _('客户') }}</b>：{{ doc.customer_name or doc.customer }}</td><td><b>{{ _('日期') }}</b>：{{ doc.posting_date }}</td></tr>
  <tr><td><b>{{ _('单号') }}</b>：{{ doc.name }}</td><td><b>{{ _('币种') }}</b>：{{ doc.currency }}</td></tr>
</table>
<table class='wholesale-items'>
  <thead><tr>{% if show_images %}<th>{{ _('图片') }}</th>{% endif %}{% if show_item_name %}<th>{{ _('Artigo / 商品') }}</th>{% endif %}{% if show_sku %}<th>{{ _('SKU / 货号') }}</th>{% endif %}{% if show_color_code %}<th>{{ _('色号 / Cor') }}</th>{% endif %}<th>{{ _('条码 / Código de barras') }}</th>{% if show_description %}<th>{{ _('描述 / Descrição') }}</th>{% endif %}<th>{{ _('数量') }}</th><th>{{ _('单位') }}</th><th>{{ _('单价') }}</th><th>{{ _('金额') }}</th></tr></thead>
  <tbody>
  {% for item in p['items'] %}
    <tr>{% if show_images %}<td>{% if item.image %}<img class='wholesale-image' src='{{ item.image | e }}' alt='{{ item.color | e }}'>{% endif %}</td>{% endif %}{% if show_item_name %}<td>{{ item.item_name | e }}</td>{% endif %}{% if show_sku %}<td>{{ item.order_code or item.item_code | e }}</td>{% endif %}{% if show_color_code %}<td>{{ item.color_code | e }}{% if item.color %}<br>{{ item.color | e }}{% endif %}</td>{% endif %}<td>{{ item.barcode | e }}</td>{% if show_description %}<td>{{ item.description | e }}</td>{% endif %}<td style='text-align:right'>{{ item.qty }}</td><td>{{ item.uom | e }}</td><td style='text-align:right'>{{ frappe.utils.fmt_money(item.rate, currency=doc.currency) }}</td><td style='text-align:right'>{{ frappe.utils.fmt_money(item.amount, currency=doc.currency) }}</td></tr>
  {% endfor %}
  </tbody>
  <tfoot><tr><td colspan='{{ 4 + show_images + show_item_name + show_sku + show_color_code + show_description }}' style='text-align:right'><b>{{ _('合计') }}</b></td><td style='text-align:right'><b>{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</b></td></tr></tfoot>
</table>
{% if doc.get('custom_print_color_qr') %}
  {% set seen = [] %}
  <div class='wholesale-qr-list'><b>{{ _('色卡') }}：</b>
  {% for item in p['items'] %}
    {% if item.template_code and item.template_code not in seen %}
      {% set _ = seen.append(item.template_code) %}
      {% set qr = get_color_card_qr_img(item.template_code) %}
      {% if qr %}<div class='wholesale-qr'><img src='{{ qr }}' alt='QR'><span>{{ item.template_code }}</span></div>{% endif %}
    {% endif %}
  {% endfor %}
  </div>
{% endif %}
